# Load energy data
with open(args.energies) as f:
    energy_data = json.load(f)

# Accept a few common schemas:
# 1) [e0, e1, ...]
# 2) {"energies": [...]}
# 3) {"energy": [...]}
if isinstance(energy_data, list):
    energies = energy_data
elif isinstance(energy_data, dict):
    if "energies" in energy_data:
        energies = energy_data["energies"]
    elif "energy" in energy_data:
        energies = energy_data["energy"]
    else:
        raise KeyError(
            "Energy JSON must be a list or contain key 'energies' (or 'energy'). "
            f"Got keys: {list(energy_data.keys())}"
        )
else:
    raise TypeError("Energy JSON must be a list or dict")

